window.__PAGES=window.__PAGES||{};window.__PAGES["pages/visits.html"]="<!-- Visit Management — Bulk Approve/Reject -->\n<style>\n.visit-toolbar{display:flex;align-items:center;gap:12px;padding:18px 24px 0;flex-wrap:wrap}\n.visit-toolbar h1{font-size:20px;font-weight:700;flex:1}\n.visit-summary{display:flex;gap:12px;padding:12px 24px}\n.visit-summary .vs{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:10px 16px;flex:1;text-align:center}\n.visit-summary .vs .num{font-size:22px;font-weight:700}.visit-summary .vs .lbl{font-size:11px;color:var(--muted)}\n.visit-table-wrap{padding:0 24px 24px;overflow-x:auto}\n.visit-status{font-size:11px;padding:2px 8px;border-radius:10px;font-weight:600;display:inline-block}\n.vs-on_plan{background:#dbeafe;color:#2563eb}.vs-waiting_review{background:#fef3c7;color:#b45309}.vs-approved{background:#dcfce7;color:#15803d}.vs-rejected{background:#fef2f2;color:#dc2626}\n/* Bulk bar */\n.bulk-bar{position:sticky;bottom:0;background:var(--card);border-top:2px solid var(--accent);padding:12px 24px;display:none;align-items:center;gap:12px;z-index:10;box-shadow:0 -4px 12px rgba(0,0,0,.1)}\n.bulk-bar.show{display:flex}\n.bulk-bar .bulk-count{font-size:14px;font-weight:600;color:var(--accent)}\n.bulk-bar .bulk-reason{flex:1;padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:13px}\n/* Detail modal */\n.visit-detail-overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);display:none;place-items:center;z-index:130}\n.visit-detail-overlay.open{display:grid}\n.visit-detail{background:var(--card);border-radius:14px;width:500px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.2);overflow:hidden}\n.vd-header{padding:16px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center}\n.vd-header h3{font-size:16px;font-weight:600}\n.vd-body{padding:20px}\n.vd-row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--bg);font-size:13px}\n.vd-row .lbl{color:var(--muted)}.vd-row .val{font-weight:500}\n.vd-actions{padding:14px 20px;border-top:1px solid var(--border);display:flex;gap:8px;justify-content:flex-end}\n.check-col{width:36px;text-align:center}\n.check-col input{width:16px;height:16px;cursor:pointer}\n</style>\n\n<div class=\"visit-toolbar\">\n  <h1>📍 Kunjungan</h1>\n  <div class=\"page-filters\" style=\"padding:0;border:none\" id=\"visitFilterBar\">\n    <span class=\"filter-chip active\" onclick=\"filterVisits(this,'all')\">Semua</span>\n    <span class=\"filter-chip\" onclick=\"filterVisits(this,'waiting_review')\">⏳ Menunggu Review</span>\n    <span class=\"filter-chip\" onclick=\"filterVisits(this,'on_plan')\">📅 Dijadwalkan</span>\n    <span class=\"filter-chip\" onclick=\"filterVisits(this,'approved')\">✅ Disetujui</span>\n    <span class=\"filter-chip\" onclick=\"filterVisits(this,'rejected')\">❌ Ditolak</span>\n  </div>\n</div>\n\n<div class=\"visit-summary\" id=\"visitSummary\"></div>\n\n<div class=\"visit-table-wrap\">\n  <table class=\"data-table\" id=\"visitTable\">\n    <thead><tr>\n      <th class=\"check-col\"><input type=\"checkbox\" id=\"selectAll\" onchange=\"toggleSelectAll(this)\"></th>\n      <th>Lead / Perusahaan</th><th>Sales</th><th>Tanggal Visit</th><th>Lokasi</th><th>Status</th><th>Catatan</th><th>Aksi</th>\n    </tr></thead>\n    <tbody id=\"visitTableBody\"></tbody>\n  </table>\n</div>\n\n<!-- Bulk action bar -->\n<div class=\"bulk-bar\" id=\"bulkBar\">\n  <span class=\"bulk-count\" id=\"bulkCount\">0 dipilih</span>\n  <button class=\"btn primary\" onclick=\"bulkApprove()\">✅ Approve Terpilih</button>\n  <input class=\"bulk-reason\" id=\"bulkRejectReason\" placeholder=\"Alasan reject (opsional untuk approve, wajib untuk reject)...\">\n  <button class=\"btn danger\" onclick=\"bulkReject()\">❌ Reject Terpilih</button>\n  <button class=\"btn\" onclick=\"clearSelection()\">Batal</button>\n</div>\n\n<!-- Visit detail modal -->\n<div class=\"visit-detail-overlay\" id=\"visitDetailOverlay\" onclick=\"if(event.target===this)closeVisitDetail()\">\n  <div class=\"visit-detail\" id=\"visitDetailContent\"></div>\n</div>\n\n<script>\nvar visitFilter='all';\nvar VISIT_STATUS={on_plan:'📅 Dijadwalkan',waiting_review:'⏳ Menunggu Review',approved:'✅ Disetujui',rejected:'❌ Ditolak'};\n\nfunction renderVisits(){\n  renderVisitSummary();\n  renderVisitTable();\n}\n\nfunction renderVisitSummary(){\n  const vs=DB.visits||[];\n  document.getElementById('visitSummary').innerHTML=`\n    <div class=\"vs\"><div class=\"num\">${vs.length}</div><div class=\"lbl\">Total</div></div>\n    <div class=\"vs\"><div class=\"num\" style=\"color:var(--warn)\">${vs.filter(v=>v.status==='waiting_review').length}</div><div class=\"lbl\">Menunggu Review</div></div>\n    <div class=\"vs\"><div class=\"num\" style=\"color:var(--accent)\">${vs.filter(v=>v.status==='on_plan').length}</div><div class=\"lbl\">Dijadwalkan</div></div>\n    <div class=\"vs\"><div class=\"num\" style=\"color:var(--ok)\">${vs.filter(v=>v.status==='approved').length}</div><div class=\"lbl\">Disetujui</div></div>\n    <div class=\"vs\"><div class=\"num\" style=\"color:var(--danger)\">${vs.filter(v=>v.status==='rejected').length}</div><div class=\"lbl\">Ditolak</div></div>\n  `;\n}\n\nfunction renderVisitTable(){\n  const visits=(DB.visits||[]).filter(v=>visitFilter==='all'||v.status===visitFilter).sort((a,b)=>new Date(b.plannedAt)-new Date(a.plannedAt));\n  const tbody=document.getElementById('visitTableBody');\n  tbody.innerHTML=visits.map(v=>{\n    const lead=dbFind('leads',v.leadId);\n    const agent=DB.agents.find(a=>a.id===v.assignee);\n    const canSelect=v.status==='waiting_review';\n    return `<tr data-id=\"${v.id}\" class=\"${canSelect?'selectable':''}\">\n      <td class=\"check-col\">${canSelect?`<input type=\"checkbox\" class=\"visit-cb\" data-id=\"${v.id}\" onchange=\"updateBulkBar()\">`:'—'}</td>\n      <td><strong>${lead?lead.company:'?'}</strong><br><span style=\"font-size:11px;color:var(--muted)\">${lead?lead.contact||'Tanpa kontak':''}</span></td>\n      <td>${agent?agent.name:'—'}</td>\n      <td>${fmtDate(v.plannedAt)}</td>\n      <td style=\"font-size:12px\">${v.location||'—'}</td>\n      <td><span class=\"visit-status vs-${v.status}\">${VISIT_STATUS[v.status]||v.status}</span></td>\n      <td style=\"font-size:12px;color:var(--muted);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">${v.note||'—'}</td>\n      <td><button class=\"btn\" style=\"font-size:12px;padding:3px 8px\" onclick=\"openVisitDetail('${v.id}')\">Detail</button></td>\n    </tr>`;\n  }).join('')||'<tr><td colspan=\"8\" style=\"text-align:center;color:var(--muted);padding:32px\">Tidak ada kunjungan</td></tr>';\n}\n\nfunction filterVisits(el,status){\n  document.querySelectorAll('#visitFilterBar .filter-chip').forEach(c=>c.classList.remove('active'));\n  el.classList.add('active');visitFilter=status;renderVisitTable();\n}\n\n// === SELECTION ===\nfunction getSelectedIds(){\n  return [...document.querySelectorAll('.visit-cb:checked')].map(cb=>cb.dataset.id);\n}\nfunction updateBulkBar(){\n  const ids=getSelectedIds();\n  const bar=document.getElementById('bulkBar');\n  bar.classList.toggle('show',ids.length>0);\n  document.getElementById('bulkCount').textContent=ids.length+' dipilih';\n}\nfunction toggleSelectAll(el){\n  document.querySelectorAll('.visit-cb').forEach(cb=>cb.checked=el.checked);\n  updateBulkBar();\n}\nfunction clearSelection(){\n  document.querySelectorAll('.visit-cb').forEach(cb=>cb.checked=false);\n  document.getElementById('selectAll').checked=false;\n  updateBulkBar();\n}\n\n// === BULK ACTIONS ===\nfunction bulkApprove(){\n  const ids=getSelectedIds();if(!ids.length)return;\n  ids.forEach(id=>{\n    dbUpdate('visits',id,{status:'approved',closedAt:new Date().toISOString(),approval:{by:DB.currentUser?.id||'u3',at:new Date().toISOString(),note:'Bulk approve'}});\n  });\n  clearSelection();renderVisits();showToast(ids.length+' kunjungan disetujui');\n}\nfunction bulkReject(){\n  const ids=getSelectedIds();if(!ids.length)return;\n  const reason=document.getElementById('bulkRejectReason').value.trim();\n  if(!reason){showToast('Alasan reject wajib diisi');return}\n  ids.forEach(id=>{\n    dbUpdate('visits',id,{status:'rejected',closedAt:new Date().toISOString(),approval:{by:DB.currentUser?.id||'u3',at:new Date().toISOString(),rejected:true,note:reason}});\n  });\n  document.getElementById('bulkRejectReason').value='';\n  clearSelection();renderVisits();showToast(ids.length+' kunjungan ditolak');\n}\n\n// === SINGLE DETAIL ===\nfunction openVisitDetail(id){\n  const v=dbFind('visits',id);if(!v)return;\n  const lead=dbFind('leads',v.leadId);\n  const agent=DB.agents.find(a=>a.id===v.assignee);\n  const approver=v.approval?DB.agents.find(a=>a.id===v.approval.by):null;\n  document.getElementById('visitDetailContent').innerHTML=`\n    <div class=\"vd-header\">\n      <h3>📍 Detail Kunjungan</h3>\n      <span class=\"visit-status vs-${v.status}\">${VISIT_STATUS[v.status]}</span>\n    </div>\n    <div class=\"vd-body\">\n      <div class=\"vd-row\"><span class=\"lbl\">Lead</span><span class=\"val\">${lead?lead.company:'—'}</span></div>\n      <div class=\"vd-row\"><span class=\"lbl\">Kontak</span><span class=\"val\">${lead?(lead.contact||'—'):'—'}</span></div>\n      <div class=\"vd-row\"><span class=\"lbl\">Sales</span><span class=\"val\">${agent?agent.name:'—'}</span></div>\n      <div class=\"vd-row\"><span class=\"lbl\">Tanggal Visit</span><span class=\"val\">${fmtDate(v.plannedAt)}</span></div>\n      <div class=\"vd-row\"><span class=\"lbl\">Lokasi</span><span class=\"val\">${v.location||'—'}</span></div>\n      <div class=\"vd-row\"><span class=\"lbl\">Catatan</span><span class=\"val\">${v.note||'—'}</span></div>\n      ${v.checkedInAt?`<div class=\"vd-row\"><span class=\"lbl\">Check-in</span><span class=\"val\">${fmtDate(v.checkedInAt)} ${fmtTime(v.checkedInAt)}</span></div>`:''}\n      ${v.outcome?`<div class=\"vd-row\"><span class=\"lbl\">Outcome</span><span class=\"val\">${v.outcome}</span></div>`:''}\n      ${v.approval?`<div style=\"border-top:1px solid var(--border);margin:10px 0;padding-top:10px\">\n        <div class=\"vd-row\"><span class=\"lbl\">${v.approval.rejected?'Ditolak':'Disetujui'} oleh</span><span class=\"val\">${approver?approver.name:'—'}</span></div>\n        <div class=\"vd-row\"><span class=\"lbl\">Waktu</span><span class=\"val\">${fmtDate(v.approval.at)}</span></div>\n        ${v.approval.note?`<div class=\"vd-row\"><span class=\"lbl\">Catatan</span><span class=\"val\">${v.approval.note}</span></div>`:''}\n      </div>`:''}\n    </div>\n    <div class=\"vd-actions\">\n      ${v.status==='on_plan'?`\n        <button class=\"btn primary\" onclick=\"singleCheckin('${v.id}')\">📍 Check-in (selesai kunjungan)</button>\n      `:''}\n      ${v.status==='waiting_review'?`\n        <button class=\"btn danger\" onclick=\"singleReject('${v.id}')\">❌ Reject</button>\n        <button class=\"btn primary\" onclick=\"singleApprove('${v.id}')\">✅ Approve</button>\n      `:''}\n      <button class=\"btn\" onclick=\"closeVisitDetail()\">Tutup</button>\n    </div>\n  `;\n  document.getElementById('visitDetailOverlay').classList.add('open');\n}\nfunction closeVisitDetail(){document.getElementById('visitDetailOverlay').classList.remove('open')}\nfunction singleCheckin(id){\n  // on_plan -> waiting_review: kunjungan selesai, kirim untuk approval\n  dbUpdate('visits',id,{status:'waiting_review',checkedInAt:new Date().toISOString(),outcome:'visited'});\n  closeVisitDetail();renderVisits();showToast('Check-in tercatat — menunggu review');\n}\nfunction singleApprove(id){\n  dbUpdate('visits',id,{status:'approved',closedAt:new Date().toISOString(),approval:{by:DB.currentUser?.id||'u3',at:new Date().toISOString(),note:'Approved'}});\n  closeVisitDetail();renderVisits();showToast('Kunjungan disetujui');\n}\nfunction singleReject(id){\n  const reason=prompt('Alasan reject:');if(!reason)return;\n  dbUpdate('visits',id,{status:'rejected',closedAt:new Date().toISOString(),approval:{by:DB.currentUser?.id||'u3',at:new Date().toISOString(),rejected:true,note:reason}});\n  closeVisitDetail();renderVisits();showToast('Kunjungan ditolak');\n}\n\nrenderVisits();\n</script>\n";
